import json
def f(g):
    h=len(g); w=len(g[0])
    rows=[r for r in range(h) if any(g[r])]
    # split into vertical blocks (consecutive nonzero rows)
    blocks=[]; cur=[rows[0]]
    for r in rows[1:]:
        if r==cur[-1]+1: cur.append(r)
        else: blocks.append(cur); cur=[r]
    blocks.append(cur)
    if len(blocks)!=2: return None
    def cols(b): return [c for c in range(w) if any(g[r][c] for r in b)]
    c1,c2=cols(blocks[0]),cols(blocks[1])
    trunc,comp=(blocks[0],blocks[1]) if max(c1)<max(c2) else (blocks[1],blocks[0])
    out=[row[:] for row in g]
    for r in trunc:
        for c in range(1,w):
            if out[r][c]==0 and comp[0] and g[comp[0]][c-1]!=0:
                # complete block rows aligned in order
                pass
    # align trunc rows to comp rows in order
    for i,r in enumerate(trunc):
        cr=comp[i]
        for c in range(1,w):
            if out[r][c]==0 and g[cr][c-1]!=0:
                out[r][c]=1
    return out
